package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"time"
)

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
	dataDir  string
}

type Session struct {
	UserID    string
	Token     string
	CreatedAt time.Time
	DataPath  string
}

func generateToken() (string, error) {
	b := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func NewSessionStore(dataDir string) *SessionStore {
	os.MkdirAll(dataDir, 0700)
	return &SessionStore{
		sessions: make(map[string]*Session),
		dataDir:  dataDir,
	}
}

func (s *SessionStore) CreateSession(userID string) (*Session, error) {
	token, err := generateToken()
	if err != nil {
		return nil, err
	}

	userDir := filepath.Join(s.dataDir, userID)
	os.MkdirAll(userDir, 0700)

	sess := &Session{
		UserID:    userID,
		Token:     token,
		CreatedAt: time.Now(),
		DataPath:  userDir,
	}

	s.mu.Lock()
	s.sessions[token] = sess
	s.mu.Unlock()

	return sess, nil
}

func (s *SessionStore) GetSession(token string) (*Session, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	sess, ok := s.sessions[token]
	return sess, ok
}

// sanitizeFilename ensures no path traversal in user-provided filenames
func sanitizeFilename(name string) string {
	// Remove any directory components
	name = filepath.Base(name)
	// Remove leading dots to prevent hidden files
	name = strings.TrimLeft(name, ".")
	if name == "" {
		name = "unnamed"
	}
	return name
}

// writeJSON safely encodes a JSON response, preventing injection via
// user-controlled values.
func writeJSON(w http.ResponseWriter, status int, payload map[string]string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(payload)
}

// sanitizeHeaderValue removes characters that could break an HTTP header
// value (quotes, backslashes and control characters).
func sanitizeHeaderValue(v string) string {
	return strings.Map(func(r rune) rune {
		if r == '"' || r == '\\' || r < 0x20 || r == 0x7f {
			return '_'
		}
		return r
	}, v)
}

// openFileNoFollow opens a file ensuring no symlinks in the final component
func openFileNoFollow(path string) (*os.File, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	return os.NewFile(uintptr(fd), path), nil
}

// verifyOpenedFileOwnership checks that an already-opened file descriptor
// points to a path within the expected directory (check-after-open pattern)
func verifyOpenedFileOwnership(f *os.File, userDir string) bool {
	// Use /proc/self/fd to get the actual path of the opened fd
	fdPath := fmt.Sprintf("/proc/self/fd/%d", f.Fd())
	realPath, err := os.Readlink(fdPath)
	if err != nil {
		return false
	}
	absUserDir, err := filepath.Abs(userDir)
	if err != nil {
		return false
	}
	resolvedDir, err := filepath.EvalSymlinks(absUserDir)
	if err != nil {
		resolvedDir = absUserDir
	}
	return strings.HasPrefix(realPath, resolvedDir+string(os.PathSeparator)) ||
		realPath == resolvedDir
}

func (s *SessionStore) HandleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	token := r.Header.Get("X-Session-Token")
	sess, ok := s.GetSession(token)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := sanitizeFilename(r.URL.Query().Get("name"))
	targetPath := filepath.Join(sess.DataPath, filename)

	// Verify the target path is within the user's directory before writing
	absTarget, err := filepath.Abs(targetPath)
	if err != nil {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}
	absDataPath, err := filepath.Abs(sess.DataPath)
	if err != nil {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}
	if !strings.HasPrefix(absTarget, absDataPath+string(os.PathSeparator)) {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}

	body := http.MaxBytesReader(w, r.Body, 5*1024*1024)
	data, err := io.ReadAll(body)
	if err != nil {
		http.Error(w, "Read error", http.StatusBadRequest)
		return
	}

	// Write with O_NOFOLLOW semantics: use O_EXCL or check no symlink
	// First remove any existing symlink at target
	info, err := os.Lstat(targetPath)
	if err == nil && info.Mode()&os.ModeSymlink != 0 {
		http.Error(w, "Cannot overwrite shared files", http.StatusForbidden)
		return
	}

	if err := os.WriteFile(targetPath, data, 0600); err != nil {
		http.Error(w, "Write error", http.StatusInternalServerError)
		return
	}

	writeJSON(w, http.StatusCreated, map[string]string{"status": "uploaded", "file": filename})
}

func (s *SessionStore) HandleDownload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	token := r.Header.Get("X-Session-Token")
	sess, ok := s.GetSession(token)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := sanitizeFilename(r.URL.Query().Get("name"))
	targetPath := filepath.Join(sess.DataPath, filename)

	// Open file with O_NOFOLLOW to prevent symlink following
	f, err := openFileNoFollow(targetPath)
	if err != nil {
		http.Error(w, "File not found", http.StatusNotFound)
		return
	}
	defer f.Close()

	// Verify the opened fd actually points within user's directory
	if !verifyOpenedFileOwnership(f, sess.DataPath) {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	data, err := io.ReadAll(f)
	if err != nil {
		http.Error(w, "Read error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=\"%s\"", sanitizeHeaderValue(filename)))
	w.Write(data)
}

func (s *SessionStore) HandleShare(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	token := r.Header.Get("X-Session-Token")
	sess, ok := s.GetSession(token)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := sanitizeFilename(r.URL.Query().Get("name"))
	targetUser := r.URL.Query().Get("target_user")

	// Validate target_user is alphanumeric
	for _, c := range targetUser {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			http.Error(w, "Invalid target user", http.StatusBadRequest)
			return
		}
	}
	if len(targetUser) == 0 || len(targetUser) > 32 {
		http.Error(w, "Invalid target user", http.StatusBadRequest)
		return
	}

	sourcePath := filepath.Join(sess.DataPath, filename)

	// Verify source file exists and is a regular file (not a symlink)
	info, err := os.Lstat(sourcePath)
	if err != nil || !info.Mode().IsRegular() {
		http.Error(w, "File not found or not shareable", http.StatusBadRequest)
		return
	}

	// Read the file content and copy it to target (no symlinks)
	data, err := os.ReadFile(sourcePath)
	if err != nil {
		http.Error(w, "Read error", http.StatusInternalServerError)
		return
	}

	targetDir := filepath.Join(s.dataDir, targetUser)
	os.MkdirAll(targetDir, 0700)
	sharedPath := filepath.Join(targetDir, "shared_"+filename)

	// Copy file content instead of creating symlinks
	if err := os.WriteFile(sharedPath, data, 0600); err != nil {
		http.Error(w, "Share failed", http.StatusInternalServerError)
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{"status": "shared", "file": "shared_" + filename})
}

func main() {
	store := NewSessionStore("/var/app/data")

	mux := http.NewServeMux()
	mux.HandleFunc("/upload", store.HandleUpload)
	mux.HandleFunc("/download", store.HandleDownload)
	mux.HandleFunc("/share", store.HandleShare)

	server := &http.Server{
		Addr:              ":8443",
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 16,
	}

	fmt.Println("Server starting on :8443")
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
